using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Runtime.InteropServices;using UnityEngine;using UnityEngine.Profiling;
[DefaultExecutionOrder(160)]public sealed class NWMetrics:MonoBehaviour {
 const string Native="I:/WGCombat/CP04BR2-1102-A/Native/BR2AllocationNative.dll";
 [DllImport(Native,CallingConvention=CallingConvention.Cdecl)]static extern int BR2Init();[DllImport(Native,CallingConvention=CallingConvention.Cdecl)]static extern void BR2Begin();[DllImport(Native,CallingConvention=CallingConvention.Cdecl)]static extern void BR2End(out ulong bytes,out ulong events,out ulong invalid);[DllImport(Native,CallingConvention=CallingConvention.Cdecl)]static extern void BR2Stop();
 [Serializable]public class Sample{public string weapon,stage,scenario;public int frame;public ulong bytes,events,invalid;public double ns;}[Serializable]class Report{public string layer,scope,status,error;public bool calibrated;public Sample[] samples;}
 public static string Scenario;public readonly List<Sample> samples=new List<Sample>();public string root;public NewWeaponCombat target;bool valid,inflight;long began;Sample current;byte[] held;
 static long Clock()=>System.Diagnostics.Stopwatch.GetTimestamp();static double Ns(long ticks)=>ticks*1e9/System.Diagnostics.Stopwatch.Frequency;
 void Measure(string stage,Action action){var row=new Sample{stage=stage};BR2Begin();long t=Clock();action();long ticks=Clock()-t;BR2End(out row.bytes,out row.events,out row.invalid);row.ns=Ns(ticks);samples.Add(row);}
 public bool Calibrate(string dir){root=dir;try{if(BR2Init()!=1)throw new Exception("Profiler init rejected");Action positive=()=>held=new byte[65536],zero=()=>{};positive();BR2Begin();BR2End(out _,out _,out _);for(int i=0;i<8;i++){Measure("zero",zero);Measure("positive-65536",positive);}valid=true;foreach(var s in samples)if(s.invalid!=0||(s.stage=="zero"?s.bytes!=0:s.bytes<65536||s.events==0))valid=false;if(!valid)throw new Exception("Allocation calibration invalid");gameObject.AddComponent<NWMetricsEnd>().owner=this;return true;}catch(Exception e){Save(e.ToString());return false;}}
 void LateUpdate(){target=CP05Training.Instance?.Hero?.GetComponent<AdventureCombat>()?.NewWeapons;if(!valid||target==null||!target.Active)return;current=new Sample{weapon=target.Combat.Gear.Weapon.ToString(),stage=target.Phase,scenario=Scenario,frame=Time.frameCount};Profiler.BeginSample("CP06B.RealNewWeaponLateInterval");BR2Begin();began=Clock();inflight=true;}
 public void EndInterval(){if(!inflight)return;long ticks=Clock()-began;BR2End(out current.bytes,out current.events,out current.invalid);Profiler.EndSample();current.ns=Ns(ticks);samples.Add(current);inflight=false;}
 public void Save(string error=null){if(!valid&&File.Exists(root+"/performance.json"))return;EndInterval();try{BR2Stop();}catch{};File.WriteAllText(root+"/performance.json",JsonUtility.ToJson(new Report{layer=Application.isEditor?"Editor":"nondevelopment Player",scope="Actual main-thread LateUpdate order160..180 interval containing NewWeaponCombat175, including physics/audio/feedback callbacks; not total frame or pure release baseline. Recorder observer overhead remains in interval. No budget asserted.",status=valid?"MEASURED":"NOT_RUN",error=error,calibrated=valid,samples=samples.ToArray()},true));valid=false;}
 void OnDestroy(){if(valid)Save();}
}
[DefaultExecutionOrder(180)]public sealed class NWMetricsEnd:MonoBehaviour{public NWMetrics owner;void LateUpdate(){owner.EndInterval();}}
